if (!state.accounts) {
  state.accounts = {
    'TR-0001': { id: 'TR-0001', iban: 'TR120006400000112345678901', name: 'Vadesiz TL', owner: 'Demo Kullanıcı', currency: 'TRY', balance: 48250.75 },
    'TR-0002': { id: 'TR-0002', iban: 'TR560006400000112345678902', name: 'Birikim', owner: 'Demo Kullanıcı', currency: 'TRY', balance: 125000 }
  };
  state.transfers = {};
  state.idempotency = {};
  state.seq = 1000;
}
const b = request.body;
const key = request.headers['idempotency-key'];
if (key && state.idempotency[key]) {
  setHeader('X-Idempotent-Replay', 'true');
  setJson(state.transfers[state.idempotency[key]]);
} else {
  const acc = state.accounts[b.fromAccountId];
  if (!acc) { setStatus(404); setJson({ error: { code: 'ACCOUNT_NOT_FOUND' } }); }
  else if (b.amount > acc.balance) {
    setStatus(422);
    setJson({ error: { code: 'INSUFFICIENT_FUNDS', message: 'Bakiye yetersiz', available: acc.balance, requested: b.amount } });
  } else {
    acc.balance = Math.round((acc.balance - b.amount) * 100) / 100;
    const id = 'TRF-' + (++state.seq);
    const t = { transferId: id, status: 'COMPLETED', fromAccountId: acc.id, toIban: b.toIban, amount: b.amount, currency: b.currency || 'TRY', balanceAfter: acc.balance, signed: !!request.headers['x-signature'], createdAt: new Date().toISOString() };
    state.transfers[id] = t;
    if (key) state.idempotency[key] = id;
    setHeader('Location', '/api/v1/transfers/' + id);
    setJson(t);
  }
}

